-- EMERGENCY ROLLBACK 074 (production). Generated by docs/releases/production-075/gen-emergency-rollback.py.
-- Run ONLY with the owner's approval, in ONE transaction:
--   psql "<production connection>" -X -v ON_ERROR_STOP=1 --single-transaction -f docs/releases/production-075/emergency/rollback_074_with_history.sql
-- Order: newest first (086, 085, 084, 083, 082, 081, 080, 079, 078, 077, 076, 075, 074, 073). Keeps every business row; removes the 074 history row so the migration history
-- matches the schema again (the plain supabase/rollback file does not touch supabase_migrations).
set lock_timeout = '10s';
set statement_timeout = '5min';
do $guard$
begin
  if to_regprocedure('public.deployment_environment()') is not null then
    raise exception 'STOP: JewelryFlow SaaS demo database, not Goldia';
  end if;
  if not exists (select 1 from supabase_migrations.schema_migrations where version = '20260101000074') then
    raise exception 'STOP: migration 074 is not recorded — nothing to roll back';
  end if;
  if exists (select 1 from supabase_migrations.schema_migrations where version > '20260101000074') then
    raise exception 'STOP: a newer migration is recorded — roll that back first';
  end if;
end $guard$;

-- ===== supabase/rollback/20260101000074_rollback.sql =====
-- ROLLBACK of 074 — restores the exact 073 state of jewelry_models / stage_loss_configs policies, defaults, grants and
-- the two model RPCs. Keeps every row. Run in one transaction:
--   psql "<connection>" -v ON_ERROR_STOP=1 --single-transaction -f supabase/rollback/20260101000074_rollback.sql
-- WARNING: this re-opens the cross-organization access that 074 closed.

do $$
declare r record;
begin
  for r in select tablename, policyname from pg_policies
            where schemaname = 'public' and tablename in ('jewelry_models', 'stage_loss_configs') loop
    execute format('drop policy %I on public.%I', r.policyname, r.tablename);
  end loop;
end $$;

create policy "authenticated read jewelry_models" on public.jewelry_models for select to authenticated using (true);
create policy "tenant managers and sales write jewelry_models" on public.jewelry_models for all to authenticated
  using (is_admin_or_manager() or (current_employee_role_text() = any (array['admin','director','manager','sales','seller','accountant']))
         or (organization_id = current_organization_id()) or (organization_id is null))
  with check (is_admin_or_manager() or (current_employee_role_text() = any (array['admin','director','manager','sales','seller','accountant']))
         or (organization_id = current_organization_id()) or (organization_id is null));
create policy "Authenticated users can read stage loss configs" on public.stage_loss_configs for select to authenticated using (true);
create policy "Admins and managers can manage stage loss configs" on public.stage_loss_configs for all to authenticated
  using (is_admin_or_manager()) with check (is_admin_or_manager());
create policy stage_loss_configs_tenant_select on public.stage_loss_configs for select to authenticated
  using ((organization_id = current_organization_id()) or (organization_id is null));
create policy stage_loss_configs_tenant_manage on public.stage_loss_configs for all to authenticated
  using ((organization_id = current_organization_id()) and (current_employee_role_text() = any (array['admin','director','owner','direktor','rahbar','manager','production_manager'])))
  with check ((organization_id = current_organization_id()) and (current_employee_role_text() = any (array['admin','director','owner','direktor','rahbar','manager','production_manager'])));

alter table public.jewelry_models alter column organization_id drop default;
alter table public.stage_loss_configs alter column organization_id drop default;

grant all on table public.jewelry_models, public.stage_loss_configs to anon, authenticated;

CREATE OR REPLACE FUNCTION public.rpc_create_jewelry_model(p_name text, p_category text DEFAULT 'Серьги'::text, p_decorations text DEFAULT NULL::text, p_reference_weight_grams numeric DEFAULT NULL::numeric, p_purity text DEFAULT '585'::text, p_model_code text DEFAULT NULL::text, p_organization_id uuid DEFAULT NULL::uuid, p_primary_image_url text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_org_id uuid;
  v_model_code text := trim(p_model_code);
  v_next_num integer;
  v_new_model record;
  v_purity_val integer;
  v_purity_text text;
  v_img_url text := nullif(trim(p_primary_image_url), '');
begin
  -- Validation: name is required
  if p_name is null or trim(p_name) = '' then
    raise exception 'Model nomi kiritilishi shart!';
  end if;

  -- Organization assignment
  v_org_id := coalesce(p_organization_id, public.current_organization_id());
  if v_org_id is null then
    select id into v_org_id from public.organizations order by created_at asc limit 1;
  end if;

  -- Advisory lock to prevent concurrent duplicate model codes
  perform pg_advisory_xact_lock(hashtext('jewelry_models_sequence_lock'));

  -- Clean and parse purity
  v_purity_text := trim(coalesce(p_purity, '585'));
  begin
    v_purity_val := nullif(regexp_replace(v_purity_text, '[^0-9]', '', 'g'), '')::integer;
  exception when others then
    v_purity_val := 585;
  end;
  if v_purity_val is null or v_purity_val <= 0 then
    v_purity_val := 585;
  end if;

  -- Generate or normalize sequential model_code (e.g. JF-M-0001, JF-M-0002)
  if v_model_code is null or v_model_code = '' or v_model_code ~* '^JF-M-0*$' then
    select coalesce(max(substring(model_code from 'JF-M-([0-9]+)')::integer), 0) + 1
      into v_next_num
      from public.jewelry_models
     where model_code ~ '^JF-M-[0-9]+';

    v_model_code := 'JF-M-' || lpad(v_next_num::text, 4, '0');
  else
    -- If custom code provided, check for duplicate collision
    if exists (select 1 from public.jewelry_models where upper(model_code) = upper(v_model_code)) then
      select coalesce(max(substring(model_code from 'JF-M-([0-9]+)')::integer), 0) + 1
        into v_next_num
        from public.jewelry_models
       where model_code ~ '^JF-M-[0-9]+';

      v_model_code := 'JF-M-' || lpad(v_next_num::text, 4, '0');
    end if;
  end if;

  -- Insert atomic record
  insert into public.jewelry_models (
    organization_id,
    model_code,
    name,
    category,
    decorations,
    reference_weight_grams,
    gold_purity,
    proba,
    primary_image_url,
    is_active
  )
  values (
    v_org_id,
    upper(v_model_code),
    trim(p_name),
    trim(coalesce(p_category, 'Серьги')),
    nullif(trim(p_decorations), ''),
    case when p_reference_weight_grams is not null and p_reference_weight_grams > 0
         then p_reference_weight_grams else null end,
    v_purity_val::text,
    v_purity_val,
    v_img_url,
    true
  )
  returning * into v_new_model;

  -- Record audit log
  if to_regclass('public.audit_logs') is not null then
    insert into public.audit_logs (
      organization_id,
      table_name,
      record_id,
      action,
      new_data,
      reason,
      created_at
    ) values (
      v_org_id,
      'jewelry_models',
      v_new_model.id::text,
      'create_model',
      jsonb_build_object(
        'model_code', v_new_model.model_code,
        'name', v_new_model.name,
        'category', v_new_model.category,
        'purity', v_purity_val,
        'weight', v_new_model.reference_weight_grams,
        'primary_image_url', v_new_model.primary_image_url
      ),
      'Created new permanent jewelry model with photo support',
      now()
    );
  end if;

  return to_jsonb(v_new_model);
end;
$function$;

CREATE OR REPLACE FUNCTION public.rpc_update_jewelry_model_photo(p_model_id uuid, p_primary_image_url text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_updated record;
begin
  update public.jewelry_models
     set primary_image_url = nullif(trim(p_primary_image_url), ''),
         updated_at = now()
   where id = p_model_id
  returning * into v_updated;

  if not found then
    raise exception 'Model topilmadi (ID: %)', p_model_id;
  end if;

  return to_jsonb(v_updated);
end;
$function$;

drop function if exists public._goldia_can_manage_models();

;
reset all;
delete from supabase_migrations.schema_migrations where version = '20260101000074';
